// Palette generator and WCAG 2.x contrast checker (scratch, not project code).
// OKLCH -> sRGB (Björn Ottosson's matrices), gamut-mapped by reducing chroma.

function oklchToLinear(L, C, h) {
  const a = C * Math.cos((h * Math.PI) / 180);
  const b = C * Math.sin((h * Math.PI) / 180);
  const l_ = L + 0.3963377774 * a + 0.2158037573 * b;
  const m_ = L - 0.1055613458 * a - 0.0638541728 * b;
  const s_ = L - 0.0894841775 * a - 1.291485548 * b;
  const l = l_ ** 3, m = m_ ** 3, s = s_ ** 3;
  return [
    4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
    -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
    -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s,
  ];
}
const enc = (x) => (x <= 0.0031308 ? 12.92 * x : 1.055 * x ** (1 / 2.4) - 0.055);
function oklch(L, C, h) {
  let c = C;
  for (;;) {
    const lin = oklchToLinear(L, c, h);
    if (lin.every((v) => v >= -1e-4 && v <= 1 + 1e-4) || c <= 0) {
      return '#' + lin.map((v) => Math.round(Math.min(1, Math.max(0, enc(v))) * 255).toString(16).padStart(2, '0')).join('').toUpperCase();
    }
    c -= 0.002;
  }
}
const hexToRgb = (hex) => [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));
const lin = (c) => { c /= 255; return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4; };
const lum = (hex) => { const [r, g, b] = hexToRgb(hex).map(lin); return 0.2126 * r + 0.7152 * g + 0.0722 * b; };
const ratio = (a, b) => { const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p); return (x + 0.05) / (y + 0.05); };
const over = (fgHex, alpha, bgHex) => '#' + hexToRgb(fgHex).map((f, i) => Math.round(f * alpha + hexToRgb(bgHex)[i] * (1 - alpha)).toString(16).padStart(2, '0')).join('').toUpperCase();

const P = {
  // ink: violet-tinted neutrals (hue 286)
  'ink-950': oklch(0.155, 0.018, 286),
  'ink-900': oklch(0.195, 0.022, 286),
  'ink-850': oklch(0.235, 0.026, 286),
  'ink-800': oklch(0.28, 0.028, 286),
  'ink-700': oklch(0.36, 0.03, 286),
  'ink-500': oklch(0.6, 0.032, 286),
  'ink-300': oklch(0.8, 0.022, 286),
  'ink-100': oklch(0.92, 0.012, 286),
  'ink-50': oklch(0.975, 0.006, 286),
  // violet (hue 293) and indigo (hue 277)
  'violet-200': oklch(0.88, 0.07, 293),
  'violet-300': oklch(0.8, 0.12, 293),
  'violet-400': oklch(0.72, 0.17, 293),
  'violet-500': oklch(0.62, 0.22, 293),
  'violet-700': oklch(0.46, 0.22, 293),
  'violet-800': oklch(0.39, 0.19, 293),
  'violet-900': oklch(0.31, 0.15, 290),
  'indigo-950': oklch(0.24, 0.1, 277),
  // status
  'red-300': oklch(0.78, 0.13, 22),
  'green-300': oklch(0.83, 0.14, 155),
  // country primitives (flag artwork; FIAV / Wikipedia approximations, not legal values)
  'flag-co-yellow': '#FFCD00',
  'flag-co-blue': '#003087',
  'flag-co-red': '#C8102E',
  'flag-cl-blue': '#0039A6',
  'flag-cl-red': '#D52B1E',
  'flag-cl-white': '#FFFFFF',
  // country accents (tints that keep the flag hue and pass 3:1 on the dark surfaces)
  'accent-co': '#FFCD00',
  'accent-cl': oklch(0.7, 0.17, 29),
  white: '#FFFFFF',
};
const dotAlpha = 0.07; // dotted texture: white dots at 7% over the page background
const S = {
  bg: P['ink-950'],
  'bg-dotted (worst)': over(P.white, dotAlpha, P['ink-950']),
  surface: P['ink-900'],
  raised: P['ink-850'],
  hover: P['ink-800'],
};
console.log('PRIMITIVES');
for (const [k, v] of Object.entries(P)) console.log(k.padEnd(16), v);
console.log('dot composited', S['bg-dotted (worst)']);

const rows = [];
const check = (fg, fgHex, bgs, min) => {
  for (const [bn, bh] of bgs) rows.push([fg, fgHex, bn, bh, ratio(fgHex, bh), min]);
};
const bgsText = [['bg', S.bg], ['bg-dotted', S['bg-dotted (worst)']], ['surface', S.surface], ['raised', S.raised], ['hover', S.hover]];
check('text (ink-50)', P['ink-50'], bgsText, 4.5);
check('text-muted (ink-300)', P['ink-300'], bgsText, 4.5);
check('link/accent text (violet-300)', P['violet-300'], bgsText, 4.5);
check('error (red-300)', P['red-300'], bgsText, 4.5);
check('success (green-300)', P['green-300'], bgsText, 4.5);
check('border-control (ink-500)', P['ink-500'], [['bg', S.bg], ['surface', S.surface], ['raised', S.raised]], 3);
check('focus ring (violet-300)', P['violet-300'], [['bg', S.bg], ['bg-dotted', S['bg-dotted (worst)']], ['surface', S.surface], ['raised', S.raised], ['rec-top violet-700', P['violet-700']], ['rec-bottom indigo-950', P['indigo-950']]], 3);
check('focus ring (violet-300)', P['violet-300'], [['button-primary bg ink-50 (inner adjacency)', P['ink-50']]], 1);
check('selected/brand (violet-400)', P['violet-400'], [['bg', S.bg], ['surface', S.surface], ['raised', S.raised]], 3);
check('icon (ink-300)', P['ink-300'], [['surface', S.surface], ['raised', S.raised]], 3);
check('button-primary text (ink-950)', P['ink-950'], [['btn top white', P.white], ['btn bottom violet-200', P['violet-200']]], 4.5);
check('button-primary bg vs page (boundary)', P['violet-200'], [['bg', S.bg], ['surface', S.surface]], 3);
check('rec card text (white)', P.white, [['rec top violet-700', P['violet-700']], ['rec mid violet-800', P['violet-800']], ['rec bottom indigo-950', P['indigo-950']]], 4.5);
check('rec card muted (violet-200)', P['violet-200'], [['rec top violet-700', P['violet-700']], ['rec mid violet-800', P['violet-800']], ['rec bottom indigo-950', P['indigo-950']]], 4.5);
check('rec card border (violet-400)', P['violet-400'], [['bg', S.bg], ['surface', S.surface]], 3);
check('display heading gradient (ink-50 stop)', P['ink-50'], [['bg', S.bg], ['bg-dotted', S['bg-dotted (worst)']]], 3);
check('display heading gradient (violet-300 stop)', P['violet-300'], [['bg', S.bg], ['bg-dotted', S['bg-dotted (worst)']]], 3);
check('accent CO (yellow)', P['accent-co'], [['bg', S.bg], ['surface', S.surface], ['header raised', S.raised]], 3);
check('accent CL (red tint)', P['accent-cl'], [['bg', S.bg], ['surface', S.surface], ['header raised', S.raised]], 3);
check('raw flag CL red (info)', P['flag-cl-red'], [['bg', S.bg], ['header raised', S.raised]], 0);
check('raw flag CL blue (info)', P['flag-cl-blue'], [['bg', S.bg], ['header raised', S.raised]], 0);
check('raw flag CO blue (info)', P['flag-co-blue'], [['bg', S.bg], ['header raised', S.raised]], 0);
check('raw flag CO red (info)', P['flag-co-red'], [['bg', S.bg], ['header raised', S.raised]], 0);
check('flag ring (ink-500)', P['ink-500'], [['header raised', S.raised]], 3);

console.log('\nCONTRAST');
let fail = 0;
for (const [fg, fh, bn, bh, r, min] of rows) {
  const ok = r >= min;
  if (!ok) fail++;
  console.log(`${fg.padEnd(40)} ${fh} on ${bn.padEnd(36)} ${bh}  ${r.toFixed(2).padStart(6)}  min ${min}  ${ok ? 'PASS' : 'FAIL'}`);
}
console.log('\nfailures:', fail);

